// ═══ SWITCH ON PRIMITIVES (JEP 507, Java 24) ═══

// switch on long (not possible before!):
String classify(long amount) {
    return switch (amount) {
        case long a when a < 0         -> "DEBIT";
        case long a when a == 0        -> "ZERO";
        case long a when a <= 100_000  -> "SMALL CREDIT";
        case long a when a <= 10_000_000 -> "MEDIUM CREDIT";
        case long a                    -> "LARGE CREDIT";
    };
}

// switch on double:
String riskLevel(double score) {
    return switch (score) {
        case double s when s >= 0.9 -> "CRITICAL";
        case double s when s >= 0.7 -> "HIGH";
        case double s when s >= 0.4 -> "MEDIUM";
        case double s               -> "LOW";
    };
}

// ═══ SAFE NARROWING in instanceof ═══
// Check if long fits in int (no overflow):
long bigValue = 2_500_000_000L;
if (bigValue instanceof int intVal) {
    // Only enters if bigValue fits in int range
    processAsInt(intVal);
}
// bigValue = 2.5B > Integer.MAX_VALUE → does NOT enter the block!

// Before JEP 507: manual range check + cast
if (bigValue >= Integer.MIN_VALUE && bigValue <= Integer.MAX_VALUE) {
    int intVal = (int) bigValue;
    processAsInt(intVal);
}
