import static org.assertj.core.api.Assertions.*;

class PrimitivePatternTest {

    @Test void switchOnLong() {
        // Conceptual test — requires Java 24+ with preview
        long amount = 50000L;
        String result = amount <= 100000 ? "SMALL" : "LARGE";
        assertThat(result).isEqualTo("SMALL");
    }

    @Test void safeNarrowingConcept() {
        long withinIntRange = 1000L;
        long outsideIntRange = 3_000_000_000L;

        // Manual safe narrowing (pre-JEP 507):
        assertThat(withinIntRange >= Integer.MIN_VALUE && withinIntRange <= Integer.MAX_VALUE).isTrue();
        assertThat(outsideIntRange >= Integer.MIN_VALUE && outsideIntRange <= Integer.MAX_VALUE).isFalse();
    }
}
