package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class PrimitivePatternTest {

    // Illustrative: classify a numeric amount's required storage width.
    String storageFor(long amount) {
        if (amount >= Integer.MIN_VALUE && amount <= Integer.MAX_VALUE) return "int";
        return "long";
    }

    @Test
    void amountFitsIntOrNeedsLong() {
        assertThat(storageFor(50_000L)).isEqualTo("int");
        assertThat(storageFor(9_000_000_000L)).isEqualTo("long"); // exceeds int range
    }
}
